import React, { useEffect, useState } from "react";
import { toast } from "react-toastify";

import {
  FiHeart,
  FiImage,
  FiRefreshCw,
  FiSave,
  FiTrash2,
  FiUploadCloud,
} from "react-icons/fi";

import api, {
  getApiErrorMessage,
} from "../../services/api";

import { useLanguage } from "../../contexts/LanguageContext";


const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  "http://127.0.0.1:8000";


const initialForm = {
  // English
  hero_title_en: "",
  hero_description_en: "",
  impact_title_en: "",
  impact_description_en: "",
  support_title_en: "",
  support_description_en: "",
  support_options_en: "",
  cta_title_en: "",
  cta_description_en: "",

  // Khmer
  hero_title_km: "",
  hero_description_km: "",
  impact_title_km: "",
  impact_description_km: "",
  support_title_km: "",
  support_description_km: "",
  support_options_km: "",
  cta_title_km: "",
  cta_description_km: "",

  // Images
  hero_image: "",
  impact_image: "",
  support_image: "",

  is_active: true,
};


const AdminCharity = () => {
  const { t, language } = useLanguage();

  const isKhmer =
    language === "km" ||
    language === "kh";


  const [form, setForm] =
    useState(initialForm);

  const [loading, setLoading] =
    useState(true);

  const [saving, setSaving] =
    useState(false);

  const [uploadingField, setUploadingField] =
    useState("");


  const tr = (
    key,
    english,
    khmer
  ) => {
    const value =
      typeof t === "function"
        ? t(key)
        : "";

    if (
      value &&
      value !== key &&
      !String(value).includes("undefined")
    ) {
      return value;
    }

    return isKhmer
      ? khmer
      : english;
  };


  const getImageUrl = (path) => {
    if (!path) {
      return "";
    }

    const imagePath = String(path);

    if (
      imagePath.startsWith("http://") ||
      imagePath.startsWith("https://") ||
      imagePath.startsWith("blob:")
    ) {
      return imagePath;
    }

    if (imagePath.startsWith("/")) {
      return `${API_BASE_URL}${imagePath}`;
    }

    return `${API_BASE_URL}/${imagePath}`;
  };


  const getErrorMessage = (
    error,
    fallback
  ) => {
    if (
      typeof getApiErrorMessage === "function"
    ) {
      return getApiErrorMessage(
        error,
        fallback
      );
    }

    const detail =
      error?.response?.data?.detail;

    if (typeof detail === "string") {
      return detail;
    }

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    return (
      error?.response?.data?.message ||
      error?.message ||
      fallback
    );
  };


  const fetchContent = async () => {
    try {
      setLoading(true);

      const response = await api.get(
        "/api/charity/"
      );

      setForm({
        ...initialForm,
        ...(response.data || {}),
      });
    } catch (error) {
      console.error(
        "Fetch charity content error:",
        error
      );

      toast.error(
        getErrorMessage(
          error,
          tr(
            "charity.loadFailed",
            "Failed to load charity content.",
            "មិនអាចទាញយកព័ត៌មានសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setLoading(false);
    }
  };


  useEffect(() => {
    fetchContent();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const handleChange = (
    field,
    value
  ) => {
    setForm((current) => ({
      ...current,
      [field]: value,
    }));
  };


  const handleImageUpload = async (
    event,
    field
  ) => {
    const file =
      event.target.files?.[0];

    if (!file) {
      return;
    }

    const allowedTypes = [
      "image/jpeg",
      "image/png",
      "image/webp",
    ];

    if (
      !allowedTypes.includes(file.type)
    ) {
      toast.error(
        tr(
          "charity.invalidImage",
          "Only JPG, PNG and WEBP images are allowed.",
          "អនុញ្ញាតតែរូបភាព JPG, PNG និង WEBP ប៉ុណ្ណោះ។"
        )
      );

      event.target.value = "";
      return;
    }

    const maxFileSize =
      5 * 1024 * 1024;

    if (file.size > maxFileSize) {
      toast.error(
        tr(
          "charity.imageTooLarge",
          "Image size must not exceed 5 MB.",
          "ទំហំរូបភាពមិនត្រូវលើសពី 5MB។"
        )
      );

      event.target.value = "";
      return;
    }

    const uploadData =
      new FormData();

    uploadData.append(
      "file",
      file
    );

    try {
      setUploadingField(field);

      const response = await api.post(
        "/api/charity/upload",
        uploadData
      );

      const imagePath =
        response.data?.path ||
        response.data?.url;

      if (!imagePath) {
        throw new Error(
          "Backend did not return an image path."
        );
      }

      setForm((current) => ({
        ...current,
        [field]: imagePath,
      }));

      toast.success(
        tr(
          "charity.imageUploaded",
          "Image uploaded successfully.",
          "បាន Upload រូបភាពដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error(
        "Upload charity image error:",
        error
      );

      toast.error(
        getErrorMessage(
          error,
          tr(
            "charity.uploadFailed",
            "Failed to upload image.",
            "មិនអាច Upload រូបភាពបានទេ។"
          )
        )
      );
    } finally {
      setUploadingField("");
      event.target.value = "";
    }
  };


  const removeImage = (field) => {
    setForm((current) => ({
      ...current,
      [field]: "",
    }));
  };


  const handleSubmit = async (
    event
  ) => {
    event.preventDefault();

    if (uploadingField) {
      toast.warning(
        tr(
          "charity.waitForUpload",
          "Please wait until the image upload is complete.",
          "សូមរង់ចាំរហូតដល់ការ Upload រូបភាពបានបញ្ចប់។"
        )
      );

      return;
    }

    try {
      setSaving(true);

      const payload = {
        ...form,

        hero_image:
          form.hero_image || null,

        impact_image:
          form.impact_image || null,

        support_image:
          form.support_image || null,

        is_active: Boolean(
          form.is_active
        ),
      };

      delete payload.id;
      delete payload.updated_at;

      const response = await api.put(
        "/api/charity/",
        payload
      );

      setForm({
        ...initialForm,
        ...(response.data || {}),
      });

      toast.success(
        tr(
          "charity.savedSuccess",
          "Charity content saved successfully.",
          "បានរក្សាទុកព័ត៌មានសប្បុរសធម៌ដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error(
        "Save charity content error:",
        error
      );

      toast.error(
        getErrorMessage(
          error,
          tr(
            "charity.saveFailed",
            "Failed to save charity content.",
            "មិនអាចរក្សាទុកព័ត៌មានសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setSaving(false);
    }
  };


  const renderInput = (
    label,
    field,
    placeholder,
    multiline = false
  ) => (
    <label className="block">
      <span className="mb-2 block text-[12px] font-semibold text-gray-700">
        {label}
      </span>

      {multiline ? (
        <textarea
          value={form[field] || ""}
          onChange={(event) =>
            handleChange(
              field,
              event.target.value
            )
          }
          placeholder={placeholder}
          rows={
            field.includes("options")
              ? 5
              : 4
          }
          className="w-full resize-y rounded-lg border border-gray-200 px-4 py-3 text-[13px] text-gray-800 outline-none transition focus:border-blue-700 focus:ring-2 focus:ring-blue-100"
        />
      ) : (
        <input
          type="text"
          value={form[field] || ""}
          onChange={(event) =>
            handleChange(
              field,
              event.target.value
            )
          }
          placeholder={placeholder}
          className="h-11 w-full rounded-lg border border-gray-200 px-4 text-[13px] text-gray-800 outline-none transition focus:border-blue-700 focus:ring-2 focus:ring-blue-100"
        />
      )}
    </label>
  );


  const renderImageUpload = (
    label,
    field,
    description
  ) => {
    const uploading =
      uploadingField === field;

    return (
      <article className="overflow-hidden rounded-xl border border-gray-200 bg-white">
        <div className="border-b border-gray-100 px-4 py-3">
          <h3 className="text-[13px] font-bold text-blue-950">
            {label}
          </h3>

          <p className="mt-1 text-[11px] leading-5 text-gray-500">
            {description}
          </p>
        </div>

        <div className="p-4">
          <div className="relative overflow-hidden rounded-xl border border-gray-200 bg-gray-100">
            <div className="relative flex aspect-[16/10] items-center justify-center">
              {form[field] ? (
                <img
                  key={form[field]}
                  src={getImageUrl(
                    form[field]
                  )}
                  alt={label}
                  className="absolute inset-0 h-full w-full object-cover"
                  onError={(event) => {
                    event.currentTarget.style.display =
                      "none";
                  }}
                />
              ) : (
                <div className="flex flex-col items-center justify-center text-gray-400">
                  <FiImage size={34} />

                  <span className="mt-2 text-[11px] font-semibold">
                    {tr(
                      "charity.noImage",
                      "No image selected",
                      "មិនទាន់មានរូបភាព"
                    )}
                  </span>
                </div>
              )}

              {uploading && (
                <div className="absolute inset-0 flex items-center justify-center bg-white/80 backdrop-blur-sm">
                  <div className="text-center">
                    <span className="mx-auto block h-8 w-8 animate-spin rounded-full border-4 border-gray-200 border-t-blue-900" />

                    <p className="mt-3 text-[11px] font-bold text-blue-950">
                      {tr(
                        "charity.uploading",
                        "Uploading...",
                        "កំពុង Upload..."
                      )}
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>

          <label
            className={`mt-4 flex min-h-[90px] cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed px-4 py-4 text-center transition ${
              uploading
                ? "cursor-not-allowed border-gray-200 bg-gray-50 opacity-60"
                : "border-gray-300 bg-gray-50 hover:border-blue-800 hover:bg-blue-50"
            }`}
          >
            <FiUploadCloud
              size={25}
              className="text-blue-900"
            />

            <span className="mt-2 text-[11px] font-bold text-blue-950">
              {form[field]
                ? tr(
                    "charity.replaceImage",
                    "Click to replace image",
                    "ចុចដើម្បីប្ដូររូបភាព"
                  )
                : tr(
                    "charity.chooseImage",
                    "Click to choose image",
                    "ចុចដើម្បីជ្រើសរើសរូបភាព"
                  )}
            </span>

